mapper.sql:
WHERE task_id = #{taskId}
  AND deleted_at IS NULL

    AND status = #{status}


    AND resumed = #{resumed}


    AND started_at >= DATE_SUB(UTC_TIMESTAMP(), INTERVAL #{days} DAY)


    AND (CAST(id AS CHAR) LIKE CONCAT('%', #{keyword}, '%')
        OR note LIKE CONCAT('%', #{keyword}, '%')
        OR error LIKE CONCAT('%', #{keyword}, '%')
        OR checkpoint_from LIKE CONCAT('%', #{keyword}, '%'))

mapper.select:
SELECT r.id, r.task_id, r.status, r.started_at, r.finished_at, r.rows_read, r.rows_written, r.error, r.note, r.resumed, r.checkpoint_from, r.checkpoint_rows, r.progress_json FROM el_resource_owners o JOIN sync_tasks t ON t.id=o.resource_id JOIN sync_runs r ON r.id=(SELECT h.id FROM sync_runs h WHERE h.task_id=t.id ORDER BY (h.status='running') DESC, h.id DESC LIMIT 1) WHERE o.resource_type='sync-task' AND o.owner_user_id=#{ownerId}
AND t.id IN #{taskId}
AND 1=0
